begin;

-- ---------------------------------------------------------------------
-- 0171_no_sale_below_cost.sql
-- ---------------------------------------------------------------------
-- 0171 The rebuild's first backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/02-money.md §8 Q16, Kevin 28 Oct 2026): no sale below
-- cost. The database refuses a line priced below its cost, except a line
-- given away on purpose, whichever app writes.
--
-- Until now only the apps refused it: Sales' priceTooLow (sales.html) and the
-- Manager's floor (manager.html decidePrice, priceChip). Nothing in SQL did:
-- 0153's ow_line_under_cost only pushes the Manager, and the gate and the
-- invoice let such a line through. A line comes under its cost two ways, and
-- the database answers each the way the apps already do:
--
--   1. Someone types it. A person (any login) writing a line's price
--      (items[].sellPrice) above 0 and under the line's cost (items[].price)
--      is refused: OWCST. Judged only when the price is new: a new line, or
--      one whose price differs from the same line before (by lineId, else
--      by product, variant and name). A cost that rises under a price set
--      earlier (the Buyer takes a supplier's dearer price) is never refused
--      here: that line waits for the Manager, as it does in the apps.
--      Writes with no login (the server's own runs, the agent and customer
--      portals, which price by rule) are judged at the bill instead.
--   2. It is billed. An order is never invoiced while a line sells under its
--      cost, whoever invoices (a phone, the console, the hourly run): OWPRC,
--      "a price still waits for the Manager", the code the apps and the
--      hourly run already route to the Manager's prices (price.approve).
--      The Manager sets a price at or above cost, or gives the line away.
--
-- Given away (items[].givenAway.why, 0169) and a line at 0 are left to
-- 0169: a 0 is free, and an invoiced 0 needs its reason (OWGIV). A line with
-- no known cost or no count is not judged. Lines already invoiced are not
-- judged again, and old orders stand until they are written or billed.
--
-- Applied by hand, after 0170. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select tgname from pg_trigger where tgname = 'saved_quotes_zz_cost_floor';
--   -- open orders that will wait for the Manager at the bill:
--   select q.id, e ->> 'productName', e ->> 'sellPrice', e ->> 'price' from saved_quotes q, jsonb_array_elements(q.payload -> 'items') e
--    where not q.invoiced and not q.voided and jsonb_typeof(e) = 'object'
--      and ow_line_sells_under_cost(q.shop_id, e, coalesce((select a.presets from app_settings a where a.shop_id = q.shop_id), '{}'));
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_zz_cost_floor on saved_quotes;
--   drop function if exists saved_quotes_cost_floor();
--   drop function if exists ow_line_sells_under_cost(uuid, jsonb, jsonb);
-- ---------------------------------------------------------------------

-- A line that sells under its cost: a count, a known cost, and a price above
-- 0 that is less (sales.html lineBelowCost: the typed price, else the
-- shop's). A 0 and a line given away are 0169's.
create or replace function ow_line_sells_under_cost(p_shop_id uuid, it jsonb, p_presets jsonb)
returns boolean
language plpgsql stable as $$
declare
  cost numeric;
  sell numeric;
  now_price numeric;
begin
  if jsonb_typeof(it) <> 'object' then return false; end if;
  if coalesce(btrim(it -> 'givenAway' ->> 'why'), '') <> '' then return false; end if;
  cost := ow_num(it ->> 'price');
  if coalesce(cost, 0) <= 0 or coalesce(ow_num(it ->> 'qty'), 0) <= 0 then return false; end if;
  sell := ow_num(it ->> 'sellPrice');
  if sell = 0 then return false; end if;
  now_price := round(case when coalesce(sell, 0) > 0 then sell else ow_line_sell_price(p_shop_id, it, p_presets) end);
  return coalesce(now_price, 0) > 0 and now_price < cost;
end $$;

create or replace function saved_quotes_cost_floor() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  items jsonb := case when jsonb_typeof(new.payload -> 'items') = 'array' then new.payload -> 'items' else '[]'::jsonb end;
  oldi jsonb := '[]'::jsonb;
  presets jsonb;
  it jsonb;
  lbl text;
begin
  -- The round's correction scripts (and only they) set this for their own transaction (0165).
  if coalesce(current_setting('ow.money_fix', true), '') = 'on' then return new; end if;
  -- An upsert of a row that is there already (the owner console saves so) is judged by its update.
  if tg_op = 'INSERT' and exists (select 1 from saved_quotes x where x.shop_id = new.shop_id and x.id = new.id) then return new; end if;
  if tg_op = 'UPDATE' and jsonb_typeof(old.payload -> 'items') = 'array' then oldi := old.payload -> 'items'; end if;
  presets := coalesce((select a.presets from app_settings a where a.shop_id = new.shop_id), '{}'::jsonb);

  -- 1. A price someone types is never under the cost.
  if auth.uid() is not null and (tg_op = 'INSERT' or items is distinct from oldi) then
    for it in select e from jsonb_array_elements(items) e loop
      continue when coalesce(ow_num(it ->> 'sellPrice'), 0) <= 0;
      continue when not ow_line_sells_under_cost(new.shop_id, it, presets);
      -- The same line at the same price before: its cost moved, not its price.
      continue when exists (select 1 from jsonb_array_elements(oldi) o
        where jsonb_typeof(o) = 'object' and ow_num(o ->> 'sellPrice') = ow_num(it ->> 'sellPrice')
          and case when it ? 'lineId' then o ->> 'lineId' = it ->> 'lineId'
                   else o ->> 'productId' is not distinct from it ->> 'productId'
                    and o ->> 'variantIdx' is not distinct from it ->> 'variantIdx'
                    and o ->> 'productName' is not distinct from it ->> 'productName' end);
      raise exception '% can''t sell at % — it costs % each. Never below cost.', coalesce(it ->> 'productName', 'A line'),
        ow_money(ow_num(it ->> 'sellPrice')), ow_money(ow_num(it ->> 'price')) using errcode = 'OWCST';
    end loop;
  end if;

  -- 2. Never billed under the cost: the Manager prices it first.
  if coalesce(new.invoiced, false) and (tg_op = 'INSERT' or not coalesce(old.invoiced, false)) then
    for it in select e from jsonb_array_elements(items) e loop
      continue when not ow_line_sells_under_cost(new.shop_id, it, presets);
      lbl := 'INV-' || case when length(new.id::text) < 4 then lpad(new.id::text, 4, '0') else new.id::text end;
      raise exception 'A price on % still waits for the Manager: % sells under its cost.', lbl, coalesce(it ->> 'productName', 'a line') using errcode = 'OWPRC';
    end loop;
  end if;
  return new;
end $$;
drop trigger if exists saved_quotes_zz_cost_floor on saved_quotes;
create trigger saved_quotes_zz_cost_floor before insert or update on saved_quotes
  for each row execute function saved_quotes_cost_floor();

-- ---------------------------------------------------------------------
-- 0172_agent_total_counts_charges.sql
-- ---------------------------------------------------------------------
-- 0172 The rebuild's second backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/02-money.md §8 Q14, Kevin 28 Oct 2026): an agent
-- order's total is its goods AND its charges.
--
-- 0109's order_shop_total, the SQL twin of orderShopTotal(), summed the
-- lines only. Its edge-function copies (agent-change-order,
-- agent-initiate-momo-payment, check-momo-payment-status) add the order's
-- charges (the agent's delivery fee). So on an order with a fee:
--
--   - apply_momo_payment marked it paid (agentPaymentStatus) once the goods
--     were covered, the fee still owed;
--   - use_agent_credit thought less was owed than the agent's app planned
--     for, refused every plan that covered the fee ('changed'), and the
--     agent was told their credit "keeps moving".
--
-- order_shop_total now counts the charges by the shop's one rule (0165's
-- ow_order_total, the functions' chargesTotal): a percent is of the goods,
-- a fixed charge whole shillings, nothing at or below 0. The two callers
-- above read it as they did; nothing else calls it.
--
-- Applied by hand, after 0171. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select order_shop_total('{"items":[{"sellPrice":1000,"qty":2}],"charges":[{"type":"fixed","value":5000},{"type":"percent","value":10}]}');  -- 7200
--
-- ROLLBACK: run 0109's order_shop_total again.
-- ---------------------------------------------------------------------

-- What the shop is owed for an agent order: sellPrice x qty, summed, and
-- the order's charges. The SQL twin of orderShopTotal() in
-- agent-change-order and of the totals in agent-initiate-momo-payment and
-- check-momo-payment-status; keep the four in step.
create or replace function public.order_shop_total(p jsonb) returns numeric
language sql immutable set search_path = public
as $$
  with goods as (
    select coalesce(sum(public.jsonb_num(it -> 'sellPrice') * public.jsonb_num(it -> 'qty')), 0) as g
      from jsonb_array_elements(case when jsonb_typeof(p -> 'items') = 'array' then p -> 'items' else '[]'::jsonb end) it
  )
  select g + coalesce((
    select sum(case when ch ->> 'type' = 'percent' then round(g * public.jsonb_num(ch -> 'value') / 100)
                    else round(public.jsonb_num(ch -> 'value')) end)
      from jsonb_array_elements(case when jsonb_typeof(p -> 'charges') = 'array' then p -> 'charges' else '[]'::jsonb end) ch
     where jsonb_typeof(ch) = 'object' and public.jsonb_num(ch -> 'value') > 0), 0)
    from goods
$$;

-- ---------------------------------------------------------------------
-- 0173_stage_moves_need_their_task.sql
-- ---------------------------------------------------------------------
-- 0173 The rebuild's third backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/01-order-journey.md §5 Q2, Kevin 28 Oct 2026): moving
-- an order's stage needs order.move, and only to an allowed next stage.
--
-- order.move (Sales, Manager) was granted but never checked: any login that
-- could write saved_quotes could set any status (ow_patch_order takes
-- p_status as given, 0165). Only store_patch_order (0164) limited its own
-- moves. Now the database checks every stage write by a person, whichever
-- path it takes. The moves the apps make, and who makes them
-- (docs/spec/01-order-journey.md §2b):
--
--   Checking → Buying | Packing     order.move, or supplier.confirm (the
--                                   Buyer, when the last supplier says yes:
--                                   buyer.html orderLeaveDraft)
--   Buying → Packing                order.move, or stock.receive
--                                   (receive_trip, the yard counts it in)
--   Packing → On the road           order.move, or order.load (the Store)
--   Packing | On the road → Delivered  order.move, or order.deliver (the Store)
--   any → Delivered                 order.move (the Manager's "mark done")
--   back to an earlier stage        order.move (the Manager's undo)
--
-- Anything else is refused (OWSTG): a skip forward other than "mark done",
-- a stage that is not one of the five, and any move on an order that is
-- invoiced or voided (manager.html obMove refused those already). A new
-- order is placed in Checking; one placed further on is judged as a move out
-- of Checking in the same write (the gate holds it there as it holds any
-- move, 0119 "held at insert too"), and one placed straight in Packing (a
-- shelf-only order, sales.html nwShelfOnly) also passes with quote.make;
-- supplier.confirm never places one.
-- A missing task is refused 42501.
--
-- Not judged: writes with no login (the Edge Functions, the hourly run, and
-- a server function's own hand after ow_system_begin, such as the counter
-- sale), and the owner's console (owner, admin), as 0169 left them. The
-- trigger runs before the Checking gate (0119), so it judges the move the
-- person asked for; the gate's own moves (sending a shelf-only order to
-- Packing, a held move made when the last yes comes) are the gate's.
--
-- Applied by hand, after 0172. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select tgname from pg_trigger where tgname = 'saved_quotes_ow_a_stage_move';
--   -- who could move what (each role's tasks):
--   select role, string_agg(task, ' ' order by task) from role_tasks
--    where task in ('order.move','supplier.confirm','stock.receive','order.load','order.deliver') group by role;
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_ow_a_stage_move on saved_quotes;
--   drop function if exists saved_quotes_stage_move();
--   drop function if exists ow_stage_word(text);
-- ---------------------------------------------------------------------

-- The word on screen for a stage (docs/audit/GLOSSARY.md).
create or replace function ow_stage_word(p_status text) returns text
language sql immutable as $$
  select case p_status when 'draft' then 'Checking' when 'awaiting_goods' then 'Buying' when 'preparing' then 'Packing'
                       when 'pending_delivery' then 'On the road' when 'completed' then 'Delivered'
                       else coalesce(nullif(p_status, ''), 'no stage') end
$$;

create or replace function saved_quotes_stage_move() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  stages text[] := array['draft', 'awaiting_goods', 'preparing', 'pending_delivery', 'completed'];
  f int;
  t int;
  tasks text[];
  k text;
  was text;
begin
  -- No login: the Edge Functions, the hourly run, a server function's own hand.
  if auth.uid() is null then return new; end if;
  -- The owner's console keeps every move (0169 left it so).
  if is_shop_admin(new.shop_id) then return new; end if;
  -- An upsert of an order already here is judged by the update it becomes.
  if tg_op = 'INSERT' and exists (select 1 from saved_quotes x where x.shop_id = new.shop_id and x.id = new.id) then return new; end if;

  -- A new order is placed in Checking; one placed further on is a move out of Checking in the same write.
  if tg_op = 'INSERT' then
    if new.status = 'draft' then return new; end if;
    was := 'draft';
  else
    if new.status is not distinct from old.status then return new; end if;
    if coalesce(old.invoiced, false) or coalesce(old.voided, false) then
      raise exception 'This order is % — its stage stays %.', case when coalesce(old.voided, false) then 'voided' else 'invoiced' end,
        ow_stage_word(old.status) using errcode = 'OWSTG';
    end if;
    was := old.status;
  end if;
  f := array_position(stages, was);
  t := array_position(stages, new.status);
  if f is null or t is null then
    raise exception 'An order can''t go from % to %.', ow_stage_word(was), ow_stage_word(new.status) using errcode = 'OWSTG';
  end if;

  tasks := case
    when t < f then array['order.move']                                         -- back (the Manager's undo)
    -- Placed straight in Packing (every line on our shelf) is placing it: quote.make.
    when tg_op = 'INSERT' and new.status = 'preparing' then array['quote.make', 'order.move']
    when tg_op = 'INSERT' and new.status = 'awaiting_goods' then array['order.move']  -- the Buyer places no orders
    when was = 'draft' and new.status in ('awaiting_goods', 'preparing') then array['order.move', 'supplier.confirm']
    when was = 'awaiting_goods' and new.status = 'preparing' then array['order.move', 'stock.receive']
    when was = 'preparing' and new.status = 'pending_delivery' then array['order.move', 'order.load']
    when was in ('preparing', 'pending_delivery') and new.status = 'completed' then array['order.move', 'order.deliver']
    when new.status = 'completed' then array['order.move']                      -- "mark done"
  end;
  if tasks is null then
    raise exception 'An order can''t go from % to %.', ow_stage_word(was), ow_stage_word(new.status) using errcode = 'OWSTG';
  end if;
  foreach k in array tasks loop
    if has_task(new.shop_id, k) then return new; end if;
  end loop;
  raise exception 'Moving an order from % to % is not yours to do (%).', ow_stage_word(was), ow_stage_word(new.status),
    array_to_string(tasks, ' or ') using errcode = '42501';
end $$;
-- Named to run before saved_quotes_ow_checking_gate (BEFORE triggers fire by name).
drop trigger if exists saved_quotes_ow_a_stage_move on saved_quotes;
create trigger saved_quotes_ow_a_stage_move before insert or update on saved_quotes
  for each row execute function saved_quotes_stage_move();

-- ---------------------------------------------------------------------
-- 0174_checking_gate_checks.sql
-- ---------------------------------------------------------------------
-- 0174 The rebuild's fourth backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/01-order-journey.md §5 Q1 and docs/spec/02-money.md
-- §8 Q8, Kevin 28 Oct 2026): the Checking gate checks what only the Buyer
-- app checked, and old debt as the apps already do.
--
-- An order leaves Checking (0119's gate, saved_quotes_ow_checking_gate) only
-- when ow_gate_reason finds nothing that holds it. It knew two reasons, a
-- price for the Manager and a credit hold. The Buyer app held an order for
-- three more before moving it (buyer.html orderLeaveDraft), and the
-- Manager's "next" and every other path skipped them. Now the gate holds a
-- move out of Checking, from any app, while:
--
--   'credit'    (widened, money Q8) the customer's oldest open debt is past
--               the hold days (presets.creditHold.days, 21 when unset;
--               sales.html creditHoldFor, manager.html creditCase), and this
--               order adds to what they owe, and the Manager has not said
--               Release (or said Cash first and it is not paid). Aged as the
--               apps age it (custOpenCharges): the debt log oldest first, a
--               payment clears its own bill first, then the oldest; a
--               charge with no date is never aged. The credit.hold push to
--               the Manager names the age.
--   'suppliers' a supplier on the order has not said yes on the terms it
--               was given (buyer.html orderDraftReady: supplierConfirms[id]
--               is 'confirmed' and its terms are the lines as they stand,
--               orderSupplierTerms).
--   'unsourced' a line has no supplier and the client is not told to wait
--               for it (buyer.html noneOpen).
--   'prepay'    an agent who pays first has not paid for it
--               (buyer.html agentPaymentBlocksPreparing).
--
-- Price and credit stay first, so the pushes that read ow_gate_reason
-- (0120's price.waits, credit.hold, price.decided; 0131's credit.decided)
-- and the counter sale (0155, which asks only about a price) see what they
-- saw before. A move held for the new reasons is kept as gateHeldMove like
-- any other, and goes on by itself with the write that clears the last
-- reason (0119 step 4d) unless the order's terms moved meanwhile.
--
-- The gate still binds every login and skips writes with no login (0119).
--
-- Applied by hand, after 0173. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   -- orders in Checking and what holds each now:
--   select id, client_name, ow_gate_reason(shop_id, payload, amount_paid) from saved_quotes
--    where status = 'draft' and not voided order by id desc limit 20;
--   select ow_oldest_debt_days(shop_id, id), name, debt from customers where debt > 0 order by 1 desc nulls last limit 10;
--
-- ROLLBACK: run 0167's ow_gate_reason again; then
--   drop function if exists ow_oldest_debt_days(uuid, text);
--   drop function if exists ow_hold_days(jsonb);
--   drop function if exists ow_supplier_terms(jsonb, text);
--   and put 0167's credit.hold wording back in saved_quotes_ow_push (re-run 0120's, then 0167's step 2).
-- ---------------------------------------------------------------------

-- The hold line in days (sales.html, manager.html holdDays).
create or replace function ow_hold_days(p_presets jsonb) returns integer
language sql immutable as $$
  select case when coalesce(ow_num(p_presets -> 'creditHold' ->> 'days'), 0) > 0
              then ow_num(p_presets -> 'creditHold' ->> 'days')::integer else 21 end
$$;

-- How many days the customer's oldest open, dated charge has been owed; 0
-- when none (sales.html custOpenCharges and custAging, rule B in
-- docs/decision-rights.md). Days by the Kampala date (ow_today).
create or replace function ow_oldest_debt_days(p_shop_id uuid, p_customer text) returns integer
language plpgsql stable security definer set search_path = public as $$
declare
  e record;
  dates date[] := '{}';
  rems numeric[] := '{}';
  qids bigint[] := '{}';
  credit numeric := 0;
  amt numeric;
  rem numeric;
  take numeric;
  i int;
  oldest int := 0;
begin
  for e in select l.date, l.type, coalesce(l.amount, 0) as amount, l.quote_id from customer_debt_log l
            where l.shop_id = p_shop_id and l.customer_id = p_customer and l.type in ('charge', 'payment')
            order by coalesce(l.date::text, ''), l.id loop
    amt := e.amount;
    if e.type = 'charge' then
      take := least(credit, amt); credit := credit - take;
      dates := dates || e.date; rems := rems || (amt - take); qids := qids || e.quote_id;
    else
      rem := amt;
      -- A payment clears its own bill first, then the oldest.
      if e.quote_id is not null then
        for i in 1 .. coalesce(array_length(rems, 1), 0) loop
          exit when rem <= 0;
          continue when qids[i] is distinct from e.quote_id;
          take := least(rems[i], rem); rems[i] := rems[i] - take; rem := rem - take;
        end loop;
      end if;
      for i in 1 .. coalesce(array_length(rems, 1), 0) loop
        exit when rem <= 0;
        take := least(rems[i], rem); rems[i] := rems[i] - take; rem := rem - take;
      end loop;
      if rem > 0 then credit := credit + rem; end if;
    end if;
  end loop;
  for i in 1 .. coalesce(array_length(rems, 1), 0) loop
    continue when rems[i] <= 0.5 or dates[i] is null;
    oldest := greatest(oldest, ow_today() - dates[i]);
  end loop;
  return oldest;
end $$;
revoke all on function ow_oldest_debt_days(uuid, text) from public, anon;
grant execute on function ow_oldest_debt_days(uuid, text) to authenticated;

-- The terms a supplier said yes to: its lines as they stand (buyer.html
-- orderSupplierTerms: productId:variantIdx:qty:price, one per line, in order).
create or replace function ow_supplier_terms(p_items jsonb, p_supplier text) returns text
language sql immutable as $$
  select coalesce(string_agg(
           coalesce(e ->> 'productId', '') || ':' || coalesce(e ->> 'variantIdx', '') || ':'
           || trim_scale(coalesce(ow_num(e ->> 'qty'), 0))::text || ':' || round(coalesce(ow_num(e ->> 'price'), 0))::text,
           '|' order by n), '')
    from jsonb_array_elements(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) with ordinality as x(e, n)
   where jsonb_typeof(e) = 'object' and e ->> 'supplierId' = p_supplier
$$;

-- What holds an order in Checking, or null when nothing does (0119, 0136,
-- 0167; 0174 adds the old debt and the three reasons after credit).
create or replace function ow_gate_reason(p_shop_id uuid, p_payload jsonb, p_amount_paid numeric)
returns text
language plpgsql stable as $$
declare
  presets jsonb := coalesce((select a.presets from app_settings a where a.shop_id = p_shop_id), '{}'::jsonb);
  items jsonb := case when jsonb_typeof(p_payload -> 'items') = 'array' then p_payload -> 'items' else '[]'::jsonb end;
  it jsonb;
  c customers;
  amt numeric;
  dec jsonb := p_payload -> 'creditCheck';
  undecided boolean;
  sid text;
  yes jsonb;
begin
  for it in select e from jsonb_array_elements(items) e loop
    if ow_line_waits_price(p_shop_id, it, presets) then return 'price'; end if;
  end loop;
  if coalesce(p_payload ->> 'customerId', '') <> '' then
    select * into c from customers where shop_id = p_shop_id and id = p_payload ->> 'customerId';
    if found then
      amt := greatest(0, round(ow_order_total(p_shop_id, p_payload, true)) - coalesce(p_amount_paid, 0));
      undecided := jsonb_typeof(dec) is distinct from 'object'
                   or dec ->> 'decision' = 'hold'
                   -- The Manager said "cash first": held until the order is paid.
                   or (dec ->> 'decision' = 'cash' and amt > 0);
      if coalesce(c.credit_limit, 0) > 0 then
        if coalesce(c.debt, 0) + amt > c.credit_limit and undecided then return 'credit'; end if;
      -- 0167: on credit with no limit set — the Manager's yes, whatever the amount.
      elsif jsonb_typeof(p_payload -> 'credit') = 'object' and coalesce(ow_num(p_payload -> 'credit' ->> 'pct'), 0) > 0 and undecided then
        return 'credit';
      end if;
      -- 0174 (money Q8): they have owed past the hold line, and this order adds to it.
      if coalesce(c.debt, 0) > 0 and amt > 0 and undecided
         and ow_oldest_debt_days(p_shop_id, c.id) > ow_hold_days(presets) then
        return 'credit';
      end if;
    end if;
  end if;
  -- 0174 (journey Q1): every supplier on the order said yes, on the lines as they stand.
  for sid in select distinct e ->> 'supplierId' from jsonb_array_elements(items) e
              where jsonb_typeof(e) = 'object' and coalesce(e ->> 'supplierId', '') not in ('', '__stock__') loop
    yes := p_payload -> 'supplierConfirms' -> sid;
    if jsonb_typeof(yes) is distinct from 'object' or yes ->> 'state' is distinct from 'confirmed'
       or yes ->> 'terms' is distinct from ow_supplier_terms(items, sid) then
      return 'suppliers';
    end if;
  end loop;
  -- A line nobody is buying, unless the client was told to wait for it.
  if exists (select 1 from jsonb_array_elements(items) e
              where jsonb_typeof(e) = 'object' and coalesce(e ->> 'supplierId', '') = ''
                and coalesce(e ->> 'clientWaits', '') in ('', 'false', '0')) then
    return 'unsourced';
  end if;
  -- An agent who pays first has paid.
  if coalesce(p_payload ->> 'originAgentId', '') <> '' and coalesce(p_payload ->> 'agentPaymentStatus', '') <> 'paid'
     and exists (select 1 from agents a where a.shop_id = p_shop_id and a.id = p_payload ->> 'originAgentId' and a.payment_term = 'prepay') then
    return 'prepay';
  end if;
  return null;
end $$;

-- The credit.hold push names an old debt's age (0167's wording, widened).
do $mig$
declare
  src text := pg_get_functiondef('public.saved_quotes_ow_push()'::regprocedure);
  was text := 'else '' · no limit set'' end';
begin
  if position('ow_oldest_debt_days' in src) > 0 then return; end if;
  if position(was in src) = 0 then raise exception '0174: saved_quotes_ow_push is not the shape 0167 left; not changed.'; end if;
  src := replace(src, was, was || chr(10) || '          || case when coalesce(c.debt, 0) > 0 and ow_oldest_debt_days(new.shop_id, c.id) > ow_hold_days(presets)'
    || ' then '' · owed '' || ow_oldest_debt_days(new.shop_id, c.id) || '' days'' else '''' end');
  execute src;
end $mig$;

-- ---------------------------------------------------------------------
-- 0175_manager_decisions_checked_on_the_writer.sql
-- ---------------------------------------------------------------------
-- 0175 The rebuild's fifth backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/01-order-journey.md §5 Q5 and Q12, Kevin 28 Oct
-- 2026): the Manager's decisions on an order are written only by whoever
-- holds the task, whichever app writes.
--
-- Four answers live in an order's payload. The Manager app writes them; the
-- database read them (the gate, the money hold, invoicing) but did not ask
-- who wrote them, except a changed priceReview object (0119's gate, step
-- 4a), which let anyone clear one (buyer.html:2912 does). Now, on every
-- write by a person:
--
--   creditCheck                  the answer to a credit hold (Release, Cash
--                                first, Hold): any change needs credit.release
--   pickSettle,                  a short pick settled (bill what went, or the
--   pickShortfallAckAt           full quantity): setting either needs
--                                pick.settle; clearing pickShortfallAckAt
--                                (a pick handed on starts again,
--                                manager.html resetPickingProgress) does not
--   creditNotes                  returns credited: any change needs
--                                credit_note.raise
--   items[].priceReview          the price decision: any change, clearing
--                                included, needs price.approve
--
-- One exception, as Kevin decided (Q12): a new cost that leaves the line
-- selling under its cost flags it for the Manager. When a write raises a
-- line's cost past the price the Manager decided, the database clears that
-- decision itself, whoever wrote, so the line waits for the Manager again
-- (0153 pushes them; 0171 keeps it off a bill). The Buyer app's own
-- clearing in that write is the same thing and passes.
--
-- Lines are matched by lineId, else by place, as 0119's step 4a matches
-- them. A new order may not carry any of these. Writes with no login are
-- not judged; the owner and admin hold every task (has_task).
--
-- Applied by hand, after 0174. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select tgname from pg_trigger where tgname = 'saved_quotes_ow_a_decisions';
--   select role, task from role_tasks where task in ('credit.release','pick.settle','credit_note.raise','price.approve') order by 2;
--
-- ROLLBACK:
--   drop trigger if exists saved_quotes_ow_a_decisions on saved_quotes;
--   drop function if exists saved_quotes_decisions();
-- ---------------------------------------------------------------------

create or replace function saved_quotes_decisions() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  np jsonb := coalesce(new.payload, '{}'::jsonb);
  op jsonb := '{}'::jsonb;
  oldi jsonb := '[]'::jsonb;
  it jsonb;
  ot jsonb;
  n int;
  nr jsonb;
  orv jsonb;
  presets jsonb;
begin
  if auth.uid() is null then return new; end if;
  -- An upsert of an order already here is judged by the update it becomes.
  if tg_op = 'INSERT' and exists (select 1 from saved_quotes x where x.shop_id = new.shop_id and x.id = new.id) then return new; end if;
  if tg_op = 'UPDATE' then
    op := coalesce(old.payload, '{}'::jsonb);
    if jsonb_typeof(op -> 'items') = 'array' then oldi := op -> 'items'; end if;
  end if;

  -- Q5: the credit answer, the short-pick settle, the credit notes.
  if nullif(np -> 'creditCheck', 'null'::jsonb) is distinct from nullif(op -> 'creditCheck', 'null'::jsonb)
     and not has_task(new.shop_id, 'credit.release') then
    raise exception 'Releasing an order held for credit is the Manager''s (credit.release).' using errcode = '42501';
  end if;
  if (nullif(np -> 'pickSettle', 'null'::jsonb) is distinct from nullif(op -> 'pickSettle', 'null'::jsonb)
      or (nullif(np -> 'pickShortfallAckAt', 'null'::jsonb) is not null
          and np -> 'pickShortfallAckAt' is distinct from op -> 'pickShortfallAckAt'))
     and not has_task(new.shop_id, 'pick.settle') then
    raise exception 'Settling a short pick is the Manager''s (pick.settle).' using errcode = '42501';
  end if;
  if coalesce(nullif(np -> 'creditNotes', 'null'::jsonb), '[]'::jsonb) is distinct from coalesce(nullif(op -> 'creditNotes', 'null'::jsonb), '[]'::jsonb)
     and not has_task(new.shop_id, 'credit_note.raise') then
    raise exception 'A credit note is the Manager''s to raise (credit_note.raise).' using errcode = '42501';
  end if;

  -- Q12: the price decision on each line.
  if jsonb_typeof(np -> 'items') = 'array' then
    presets := coalesce((select a.presets from app_settings a where a.shop_id = new.shop_id), '{}'::jsonb);
    n := 0;
    for it in select e from jsonb_array_elements(np -> 'items') e loop
      n := n + 1;
      continue when jsonb_typeof(it) <> 'object';
      select e into ot from jsonb_array_elements(oldi) with ordinality as x(e, k)
       where (it ? 'lineId' and e ->> 'lineId' = it ->> 'lineId') or (not it ? 'lineId' and k = n)
       limit 1;
      nr := nullif(it -> 'priceReview', 'null'::jsonb);
      orv := case when jsonb_typeof(ot) = 'object' then nullif(ot -> 'priceReview', 'null'::jsonb) end;
      -- A cost raised past the price decided: the decision falls away, and the line waits for the Manager.
      if orv is not null and coalesce(ow_num(it ->> 'price'), 0) > coalesce(ow_num(ot ->> 'price'), 0)
         and ow_line_sells_under_cost(new.shop_id, it, presets) then
        if nr is not null then new.payload := jsonb_set(new.payload, array['items', (n - 1)::text, 'priceReview'], 'null'::jsonb); end if;
        continue;
      end if;
      continue when nr is not distinct from orv;
      if not has_task(new.shop_id, 'price.approve') then
        raise exception 'A price decision is the Manager''s (price.approve).' using errcode = '42501';
      end if;
    end loop;
  end if;
  return new;
end $$;
-- Named to run before saved_quotes_ow_checking_gate (BEFORE triggers fire by name).
drop trigger if exists saved_quotes_ow_a_decisions on saved_quotes;
create trigger saved_quotes_ow_a_decisions before insert or update on saved_quotes
  for each row execute function saved_quotes_decisions();

-- ---------------------------------------------------------------------
-- 0176_void_and_credit_note_one_write.sql
-- ---------------------------------------------------------------------
-- 0176 The rebuild's sixth backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/01-order-journey.md §5 Q6, Kevin 28 Oct 2026): a void
-- and a credit note are each one database write, like payments and the
-- counter sale.
--
-- The Manager app does each as several calls (manager.html voidAskWrite,
-- ACT['slide:credit']): the why on the order, the void (or 0169's
-- void_with_money), the goods back on the shelf (manager_stock_move), the
-- supplier bills voided (void_sale_bills), the ask closed
-- (decide_invoice_ask); for a credit note the note on the order, the goods
-- back, the ask closed, the log line. A lost signal between two of them left
-- half of one: voided with the goods still off the shelf, a credit note with
-- its ask still open. Now each is one function, one transaction: all of it,
-- or none of it.
--
--   void_invoice(shop, order, why, restock, choice, account, ask)
--       invoice.void. An invoiced order only (before the bill it is a
--       cancel). The why on the order (payload.voidedBy) and its docLog
--       line; the void with its money, refund or deposit, and the supplier
--       bills (void_with_money, 0169); with restock, what the invoice took
--       off the shelf (items[]._stockTaken, 0119) back on it; the ask
--       accepted.
--   raise_credit_note(shop, order, lines, reason, cash_back, ask)
--       credit_note.raise. lines [{idx, qty, restock}]. Each line's price is
--       what it sold at (its typed price, else the shop's), never more than
--       the line has left to credit; the note's number from the shop's one
--       sequence (row:credit_note, as the console numbers them); the note
--       and its docLog line on the order (the bill and the balance follow,
--       0165, 0169); with restock, the goods back; the ask accepted; the
--       owner's log.
--
-- The old Manager app keeps its own path (it is frozen while its new app is
-- built, docs/rebuild.md rule 4); the new apps call these.
--
-- Applied by hand, after 0175. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select proname from pg_proc where proname in ('void_invoice', 'raise_credit_note');
--
-- ROLLBACK:
--   drop function if exists void_invoice(uuid, bigint, text, boolean, text, text, uuid);
--   drop function if exists raise_credit_note(uuid, bigint, jsonb, text, boolean, uuid);
-- ---------------------------------------------------------------------

-- The ask a void or a credit note answers: on this order, of this kind, still open.
create or replace function ow_open_ask(p_ask uuid, p_order bigint, p_kind text) returns void
language plpgsql security definer set search_path = public as $$
declare a invoice_asks%rowtype;
begin
  select * into a from invoice_asks where id = p_ask for update;
  if not found or a.quote_id is distinct from p_order or a.kind is distinct from p_kind then
    raise exception 'That ask is not for this order.' using errcode = '22023';
  end if;
  if a.status <> 'sent' then raise exception 'That ask is % already.', a.status using errcode = '22023'; end if;
end $$;
revoke all on function ow_open_ask(uuid, bigint, text) from public, anon, authenticated;

create or replace function void_invoice(p_shop_id uuid, p_order bigint, p_why text, p_restock boolean default false,
  p_choice text default null, p_account text default 'cash', p_ask uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  q saved_quotes%rowtype;
  why text := nullif(btrim(coalesce(p_why, '')), '');
  lbl text;
  now_iso text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  res jsonb;
  back jsonb;
begin
  if uid is null or not is_shop_member(p_shop_id) then
    raise exception 'Not a member of this shop.' using errcode = '42501';
  end if;
  if not has_task(p_shop_id, 'invoice.void') then
    raise exception 'Voiding an order is the Manager''s (invoice.void).' using errcode = '42501';
  end if;
  if why is null then raise exception 'Say why it is voided.' using errcode = '22023'; end if;
  select * into q from saved_quotes where shop_id = p_shop_id and id = p_order for update;
  if not found then raise exception 'This order is no longer in the books.' using errcode = 'P0002'; end if;
  if coalesce(q.voided, false) then raise exception 'This order is voided already.' using errcode = '22023'; end if;
  if not coalesce(q.invoiced, false) then
    raise exception 'Only an invoice is voided; an order not billed yet is cancelled.' using errcode = '22023';
  end if;
  lbl := 'INV-' || case when length(q.id::text) < 4 then lpad(q.id::text, 4, '0') else q.id::text end;
  if p_ask is not null then perform ow_open_ask(p_ask, q.id, 'void'); end if;

  -- The why first, then the void with its money and the supplier bills (0169).
  update saved_quotes
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
           'voidedBy', jsonb_build_object('by', uid, 'byName', ow_member_name(p_shop_id, uid), 'at', now_iso, 'why', left(why, 100), 'askId', p_ask),
           'docLog', (select coalesce(jsonb_agg(e order by k), '[]'::jsonb) from (
                        select e, k from jsonb_array_elements(
                          coalesce(case when jsonb_typeof(payload -> 'docLog') = 'array' then payload -> 'docLog' end, '[]'::jsonb)
                          || jsonb_build_array(jsonb_build_object('at', now_iso, 'kind', 'voided', 'what', 'Voided · ' || left(why, 100))))
                          with ordinality as x(e, k) order by k desc limit 60) l))
   where shop_id = p_shop_id and id = q.id;
  res := void_with_money(p_shop_id, q.id, p_choice, p_account);

  -- Back on the shelf: what the invoice took off it, never the line's quantity.
  if coalesce(p_restock, false) then
    select coalesce(jsonb_agg(jsonb_build_object(
             'key', (e ->> 'productId') || case when coalesce(e ->> 'variantIdx', '') <> '' then '::' || (e ->> 'variantIdx') else '' end,
             'productId', e ->> 'productId', 'variantIdx', e -> 'variantIdx', 'name', coalesce(e ->> 'productName', 'Item'),
             'delta', ow_num(e ->> '_stockTaken'), 'cost', nullif(ow_num(e ->> 'price'), 0))), '[]'::jsonb)
      into back
      from jsonb_array_elements(case when jsonb_typeof(q.payload -> 'items') = 'array' then q.payload -> 'items' else '[]'::jsonb end) e
     where jsonb_typeof(e) = 'object' and coalesce(e ->> 'productId', '') <> '' and coalesce(ow_num(e ->> '_stockTaken'), 0) > 0;
    if jsonb_array_length(back) > 0 then
      perform manager_stock_move(p_shop_id, back, 'reversal', 'Voided — ' || lbl, 'invoice.void');
    end if;
  end if;
  if p_ask is not null then perform decide_invoice_ask(p_ask, 'accepted'); end if;
  return res || jsonb_build_object('invoice', lbl, 'restocked', coalesce(jsonb_array_length(back), 0));
end $$;
revoke all on function void_invoice(uuid, bigint, text, boolean, text, text, uuid) from public, anon;
grant execute on function void_invoice(uuid, bigint, text, boolean, text, text, uuid) to authenticated;

create or replace function raise_credit_note(p_shop_id uuid, p_order bigint, p_lines jsonb, p_reason text,
  p_cash_back boolean default false, p_ask uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  q saved_quotes%rowtype;
  presets jsonb;
  items jsonb;
  it jsonb;
  l jsonb;
  idx int;
  qty numeric;
  room numeric;
  price numeric;
  lines jsonb := '[]'::jsonb;
  back jsonb := '[]'::jsonb;
  seen int[] := '{}';
  amount numeric;
  no bigint;
  floor_no bigint;
  cn jsonb;
  lbl text;
  cnl text;
  before_total numeric;
  now_iso text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
begin
  if uid is null or not is_shop_member(p_shop_id) then
    raise exception 'Not a member of this shop.' using errcode = '42501';
  end if;
  if not has_task(p_shop_id, 'credit_note.raise') then
    raise exception 'A credit note is the Manager''s to raise (credit_note.raise).' using errcode = '42501';
  end if;
  select * into q from saved_quotes where shop_id = p_shop_id and id = p_order for update;
  if not found then raise exception 'This order is no longer in the books.' using errcode = 'P0002'; end if;
  if coalesce(q.voided, false) or not coalesce(q.invoiced, false) then
    raise exception 'A credit note is raised on a live invoice.' using errcode = '22023';
  end if;
  if p_ask is not null then perform ow_open_ask(p_ask, q.id, 'credit'); end if;
  lbl := 'INV-' || case when length(q.id::text) < 4 then lpad(q.id::text, 4, '0') else q.id::text end;
  presets := coalesce((select a.presets from app_settings a where a.shop_id = p_shop_id), '{}'::jsonb);
  items := case when jsonb_typeof(q.payload -> 'items') = 'array' then q.payload -> 'items' else '[]'::jsonb end;

  for l in select e from jsonb_array_elements(case when jsonb_typeof(p_lines) = 'array' then p_lines else '[]'::jsonb end) e loop
    idx := (l ->> 'idx')::int;
    qty := coalesce(ow_num(l ->> 'qty'), 0);
    continue when not (qty > 0);
    it := items -> idx;
    if idx is null or idx < 0 or jsonb_typeof(it) is distinct from 'object' then
      raise exception 'A line on the credit note is not on %.', lbl using errcode = '22023';
    end if;
    if idx = any(seen) then raise exception 'A line is named twice on the credit note.' using errcode = '22023'; end if;
    seen := seen || idx;
    -- What the line has left to credit (manager.html creditedQty: notes not voided).
    select coalesce(ow_num(it ->> 'qty'), 0) - coalesce(sum(coalesce(ow_num(cl ->> 'qty'), 0)), 0) into room
      from jsonb_array_elements(case when jsonb_typeof(q.payload -> 'creditNotes') = 'array' then q.payload -> 'creditNotes' else '[]'::jsonb end) c,
           jsonb_array_elements(case when jsonb_typeof(c -> 'lines') = 'array' then c -> 'lines' else '[]'::jsonb end) cl
     where jsonb_typeof(c) = 'object' and coalesce(c ->> 'voided', 'false') <> 'true' and (cl ->> 'idx')::int = idx;
    if qty > room + 0.000001 then
      raise exception '%: only % left to credit.', coalesce(it ->> 'productName', 'A line'), trim_scale(greatest(room, 0)) using errcode = '22023';
    end if;
    -- What it sold at, each (manager.html linePriceNow).
    price := round(case when coalesce(ow_num(it ->> 'sellPrice'), 0) > 0 then ow_num(it ->> 'sellPrice')
                        else coalesce(ow_line_sell_price(p_shop_id, it, presets), 0) end);
    lines := lines || jsonb_build_array(jsonb_build_object('idx', idx, 'qty', qty, 'price', price, 'name', coalesce(it ->> 'productName', 'Item')));
    if coalesce(l ->> 'restock', '') = 'true' and coalesce(it ->> 'productId', '') <> '' then
      back := back || jsonb_build_array(jsonb_build_object(
        'key', (it ->> 'productId') || case when coalesce(it ->> 'variantIdx', '') <> '' then '::' || (it ->> 'variantIdx') else '' end,
        'productId', it ->> 'productId', 'variantIdx', it -> 'variantIdx', 'name', coalesce(it ->> 'productName', 'Item'),
        'delta', qty, 'cost', nullif(ow_num(it ->> 'price'), 0)));
    end if;
  end loop;
  if jsonb_array_length(lines) = 0 then raise exception 'Pick at least one line.' using errcode = '22023'; end if;
  select round(sum(ow_num(x ->> 'qty') * ow_num(x ->> 'price'))) into amount from jsonb_array_elements(lines) x;

  -- One number for the shop, as the console numbers credit notes.
  select coalesce(max(ow_num(c ->> 'no')), 0)::bigint into floor_no
    from saved_quotes s, jsonb_array_elements(case when jsonb_typeof(s.payload -> 'creditNotes') = 'array' then s.payload -> 'creditNotes' else '[]'::jsonb end) c
   where s.shop_id = p_shop_id and jsonb_typeof(c) = 'object';
  no := ow_reserve_row_ids(p_shop_id, 'row:credit_note', floor_no, 1);
  cnl := 'CN-' || lpad(no::text, 4, '0');
  cn := jsonb_build_object('id', no, 'no', no, 'date', ow_today()::text, 'reason', left(coalesce(btrim(p_reason), ''), 300),
          'lines', lines, 'amount', amount, 'restocked', jsonb_array_length(back) > 0,
          'refund', case when coalesce(p_cash_back, false) then jsonb_build_object('amount', amount, 'due', true, 'account', null) end,
          'askId', p_ask, 'by', uid, 'byName', ow_member_name(p_shop_id, uid));
  before_total := round(ow_order_total(p_shop_id, q.payload, false));
  -- The note on the invoice: the bill and the balance follow it (0165, 0169 refuse one past the bill).
  update saved_quotes
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
           'creditNotes', coalesce(case when jsonb_typeof(payload -> 'creditNotes') = 'array' then payload -> 'creditNotes' end, '[]'::jsonb) || jsonb_build_array(cn),
           'docLog', (select coalesce(jsonb_agg(e order by k), '[]'::jsonb) from (
                        select e, k from jsonb_array_elements(
                          coalesce(case when jsonb_typeof(payload -> 'docLog') = 'array' then payload -> 'docLog' end, '[]'::jsonb)
                          || jsonb_build_array(jsonb_build_object('at', now_iso, 'kind', 'credited', 'what', cnl || ' raised · ' || ow_money(amount))))
                          with ordinality as x(e, k) order by k desc limit 60) d))
   where shop_id = p_shop_id and id = q.id
  returning * into q;
  if jsonb_array_length(back) > 0 then
    perform manager_stock_move(p_shop_id, back, 'reversal', 'Returned — ' || cnl || ' on ' || lbl, 'credit_note.raise');
  end if;
  if p_ask is not null then perform decide_invoice_ask(p_ask, 'accepted'); end if;
  perform manager_log_decision(p_shop_id, 'credit_note.raise',
    'Credit note ' || cnl || ' · ' || ow_money(amount) || ' on ' || lbl || coalesce(' for ' || nullif(q.client_name, ''), '')
      || case when coalesce(p_cash_back, false) then ' · cash back by Accounts' else '' end,
    amount, jsonb_build_object('table', 'saved_quotes', 'id', q.id, 'creditNote', no),
    jsonb_build_object('total', before_total), jsonb_build_object('total', round(ow_order_total(p_shop_id, q.payload, false))));
  return jsonb_build_object('ok', true, 'orderId', q.id, 'no', no, 'label', cnl, 'amount', amount,
                            'restocked', jsonb_array_length(back), 'creditNote', cn);
end $$;
revoke all on function raise_credit_note(uuid, bigint, jsonb, text, boolean, uuid) from public, anon;
grant execute on function raise_credit_note(uuid, bigint, jsonb, text, boolean, uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 0177_one_cancel.sql
-- ---------------------------------------------------------------------
-- 0177 The rebuild's seventh backend fix (docs/rebuild.md, "Backend fixes
-- decided"; docs/spec/01-order-journey.md §5 Q7 and Q8, Kevin 28 Oct 2026):
-- one Cancel, by the Manager (order.cancel), before an order is invoiced.
--
-- Three ways called an order off, each its own way: the console's Cancel
-- (index.html cancelSavedQuote: voided + cancelledAt), the Manager's void of
-- a duplicate (manager.html obVoidDup), and an agent's cancel. None set the
-- stage the Store screen reads (store.html orderCalledOff:
-- status = 'cancelled', cancelledAt, cancelledByName), and nobody told the
-- Store to stop packing. Now:
--
--   cancel_order(shop, order, why, choice, account)
--       order.cancel (the Manager; decision-rights row "Cancel an order
--       before it is invoiced", built here). In one write: status
--       'cancelled' and voided, with cancelledAt (ms, as the console writes
--       it), cancelledBy, cancelledByName, cancelWhy, the stage log and a
--       docLog line; money paid on it refunded or kept as a deposit
--       (voidMoney, as 0169's void_with_money does). Then pushes:
--       'order.cancelled' to the Store (order.pick) when it was in the yard
--       (Packing or On the road) — stop, put back what is out, as the Store
--       screen already shows (store.html pkCancel) — and to the salesperson
--       who took it. The owner's log line comes from the void guard.
--
--   Refused: an invoiced order (that is a void, invoice.void) or a
--   delivered one (invoice it, then void it); one whose bought-in goods came
--   in, or that is on a live buying trip (manager.html obVoidBlock: the
--   supplier is billed, or the trip changed, first); money paid with no
--   choice made (OWVMN).
--
-- Stock moves at the invoice (0119), so nothing comes off the books here:
-- what the yard picked goes back by hand, which the push asks for.
--
-- Also: 0173's stage rule knows 'cancelled' (only with order.cancel, never
-- from Delivered or an invoice, and never back out of it), and 0122's void
-- guard takes order.cancel for a cancel and logs it as one.
--
-- Not built (not decided as a database rule): Sales asking for a cancel
-- (the "Proposes: Sales" column; today they ask the Manager directly), and
-- the console's billing of goods that came in before a cancel.
--
-- Applied by hand, after 0176. Safe to run twice.
--
-- CHECK AFTERWARDS:
--   select role, task from role_tasks where task = 'order.cancel';
--   select id, status, voided, payload ->> 'cancelledByName' from saved_quotes where status = 'cancelled' order by id desc limit 5;
--
-- ROLLBACK:
--   drop function if exists cancel_order(uuid, bigint, text, text, text);
--   drop function if exists ow_settle_void_money(uuid, saved_quotes, text, text, text);
--   delete from role_tasks where task = 'order.cancel';
--   then run 0173's saved_quotes_stage_move and 0122's saved_quotes_sales_guard again.
-- ---------------------------------------------------------------------

insert into role_tasks (role, task) values ('manager', 'order.cancel') on conflict do nothing;

-- ---------------------------------------------------------------------
-- 1. 0173's stage rule: 'cancelled' is the Manager's, and final.
do $mig$
declare
  src text := pg_get_functiondef('saved_quotes_stage_move()'::regprocedure);
  was text := '    if new.status is not distinct from old.status then return new; end if;' || chr(10);
begin
  if position('order.cancel' in src) > 0 then return; end if;
  if position(was in src) = 0 then raise exception '0177: saved_quotes_stage_move is not the shape 0173 left; not changed.'; end if;
  src := replace(src, was, was
    || '    -- 0177: Cancel (order.cancel), before the bill; it is final.' || chr(10)
    || '    if new.status = ''cancelled'' then' || chr(10)
    || '      if coalesce(old.invoiced, false) or old.status = ''completed'' then' || chr(10)
    || '        raise exception ''A delivered or invoiced order is not cancelled: invoice it, then void it.'' using errcode = ''OWSTG'';' || chr(10)
    || '      end if;' || chr(10)
    || '      if coalesce(old.voided, false) then raise exception ''This order is voided already.'' using errcode = ''OWSTG''; end if;' || chr(10)
    || '      if has_task(new.shop_id, ''order.cancel'') then return new; end if;' || chr(10)
    || '      raise exception ''Cancelling an order is the Manager''''s (order.cancel).'' using errcode = ''42501'';' || chr(10)
    || '    end if;' || chr(10));
  execute src;
end $mig$;

-- ---------------------------------------------------------------------
-- 2. 0122's void guard: a cancel is voided by order.cancel, and logged as a cancel.
do $mig$
declare
  src text := pg_get_functiondef('saved_quotes_sales_guard()'::regprocedure);
  was1 text := '    if has_task(new.shop_id, ''invoice.void'') then' || chr(10) || '      v_task := ''invoice.void'';';
  was2 text := 'case when v_task = ''agent.change'' then ''Closed an agent''''s cancelled order #'' else ''Voided order #'' end';
begin
  if position('order.cancel' in src) > 0 then return; end if;
  if position(was1 in src) = 0 or position(was2 in src) = 0 then
    raise exception '0177: saved_quotes_sales_guard is not the shape 0122 left; not changed.';
  end if;
  src := replace(src, was1,
       '    -- 0177: Cancel, before the bill (order.cancel).' || chr(10)
    || '    if new.status = ''cancelled'' and not coalesce(old.invoiced, false) and has_task(new.shop_id, ''order.cancel'') then' || chr(10)
    || '      v_task := ''order.cancel'';' || chr(10)
    || '    elsif has_task(new.shop_id, ''invoice.void'') then' || chr(10) || '      v_task := ''invoice.void'';');
  src := replace(src, was2,
    'case v_task when ''agent.change'' then ''Closed an agent''''s cancelled order #'' when ''order.cancel'' then ''Cancelled order #'' else ''Voided order #'' end');
  execute src;
end $mig$;

-- ---------------------------------------------------------------------
-- 3. The money paid on an order that is called off: refunded, or kept as
-- the customer's deposit (0169 void_with_money's two ways). Returns the
-- voidMoney record that goes in the same write as the void.
create or replace function ow_settle_void_money(p_shop_id uuid, q saved_quotes, p_choice text, p_account text, p_label text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  choice text := nullif(lower(btrim(coalesce(p_choice, ''))), '');
  acct text := coalesce(nullif(lower(btrim(coalesce(p_account, ''))), ''), 'cash');
  amt numeric := round(coalesce(q.amount_paid, 0));
  cid text := nullif(q.payload ->> 'customerId', '');
  cash_id bigint;
  floor_id bigint;
  saved jsonb;
begin
  if choice is not null and choice not in ('refund', 'deposit') then
    raise exception 'The money is refunded or kept as a deposit.' using errcode = '22023';
  end if;
  if amt > 0 and choice is null then
    raise exception '% was paid on %: refund it, or keep it as a deposit.', ow_money(amt), p_label using errcode = 'OWVMN';
  end if;
  if amt > 0 and choice = 'deposit' then
    perform 1 from customers where shop_id = p_shop_id and id = cid for update;
    if cid is null or not found then raise exception 'Name the customer to keep a deposit.' using errcode = 'OWDEP'; end if;
    saved := ow_system_begin();
    update customers set debt = coalesce(debt, 0) - amt where shop_id = p_shop_id and id = cid;
    select coalesce(max(id), 0) into floor_id from customer_debt_log where shop_id = p_shop_id;
    insert into customer_debt_log (id, shop_id, customer_id, date, type, amount, note, quote_id)
         values (ow_next_row_id(p_shop_id, 'row:debt_log', floor_id), p_shop_id, cid, ow_today(), 'payment', amt, 'Deposit — ' || p_label, null);
    perform ow_system_end(saved);
  end if;
  if amt > 0 and choice = 'refund' then
    cash_id := ow_next_row_id(p_shop_id, 'row:cash_txn', 0);
    insert into cash_txns (id, shop_id, date, account, type, category, amount, description, time, quote_id, entered_by)
         values (cash_id, p_shop_id, ow_today(), acct, 'payment', 'Refund', amt, 'Refund — ' || p_label || coalesce(' · ' || nullif(q.client_name, ''), ''),
                 to_char(now() at time zone ow_shop_tz(), 'HH24:MI'), q.id, uid);
  end if;
  return jsonb_build_object('done', true, 'choice', case when amt > 0 then choice else 'none' end, 'amount', amt,
                            'account', case when amt > 0 and choice = 'refund' then acct end, 'cashTxnId', cash_id,
                            'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), 'by', uid);
end $$;
revoke all on function ow_settle_void_money(uuid, saved_quotes, text, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. The Cancel.
create or replace function cancel_order(p_shop_id uuid, p_order bigint, p_why text, p_choice text default null, p_account text default 'cash')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  q saved_quotes%rowtype;
  why text := nullif(btrim(coalesce(p_why, '')), '');
  lbl text;
  who text;
  client text;
  now_ms numeric := floor(extract(epoch from clock_timestamp()) * 1000);
  now_iso text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  vm jsonb;
  in_yard boolean;
  taker uuid;
  ref jsonb;
begin
  if uid is null or not is_shop_member(p_shop_id) then
    raise exception 'Not a member of this shop.' using errcode = '42501';
  end if;
  if not has_task(p_shop_id, 'order.cancel') then
    raise exception 'Cancelling an order is the Manager''s (order.cancel).' using errcode = '42501';
  end if;
  if why is null then raise exception 'Say why it is cancelled.' using errcode = '22023'; end if;
  select * into q from saved_quotes where shop_id = p_shop_id and id = p_order for update;
  if not found then raise exception 'This order is no longer in the books.' using errcode = 'P0002'; end if;
  lbl := '#' || lpad(q.id::text, 4, '0');
  if coalesce(q.voided, false) then raise exception '% is called off already.', lbl using errcode = '22023'; end if;
  if coalesce(q.invoiced, false) then raise exception '% is invoiced: void it instead (invoice.void).', lbl using errcode = '22023'; end if;
  if q.status = 'completed' then raise exception '% was delivered: invoice it, then void it.', lbl using errcode = '22023'; end if;
  -- manager.html obVoidBlock: goods bought for it came in, or a buying trip carries it.
  if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(q.payload -> 'items') = 'array' then q.payload -> 'items' else '[]'::jsonb end) e
              where jsonb_typeof(e) = 'object' and coalesce(e ->> 'supplierId', '') not in ('', '__stock__')
                and coalesce(e ->> 'receivedAt', '') <> '' and coalesce(ow_num(e ->> 'receivedQty'), 0) > 0) then
    raise exception 'Goods bought for % came in: their supplier is billed first.', lbl using errcode = '22023';
  end if;
  if exists (select 1 from collection_trips t, jsonb_array_elements(case when jsonb_typeof(t.lines) = 'array' then t.lines else '[]'::jsonb end) l
              where t.shop_id = p_shop_id and not t.voided and t.status <> 'confirmed' and l ->> 'orderId' = q.id::text) then
    raise exception 'A buying trip carries %: take it off the trip first.', lbl using errcode = '22023';
  end if;

  vm := ow_settle_void_money(p_shop_id, q, p_choice, p_account, 'cancel ' || lbl);
  who := ow_member_name(p_shop_id, uid);
  in_yard := q.status in ('preparing', 'pending_delivery');
  -- One write: the stage, the void, the money, who and why (the void guard logs it as a cancel).
  update saved_quotes
     set status = 'cancelled', voided = true,
         payload = (coalesce(payload, '{}'::jsonb) - 'gateHeldMove') || jsonb_build_object(
           'voidMoney', vm, 'cancelledAt', now_ms, 'cancelledBy', uid, 'cancelledByName', who, 'cancelWhy', left(why, 200),
           'stageEnteredAt', now_ms,
           'stageLog', coalesce(case when jsonb_typeof(payload -> 'stageLog') = 'array' then payload -> 'stageLog' end, '[]'::jsonb)
                       || jsonb_build_array(jsonb_build_object('status', 'cancelled', 'at', now_ms, 'by', 'manager')),
           'docLog', (select coalesce(jsonb_agg(e order by k), '[]'::jsonb) from (
                        select e, k from jsonb_array_elements(
                          coalesce(case when jsonb_typeof(payload -> 'docLog') = 'array' then payload -> 'docLog' end, '[]'::jsonb)
                          || jsonb_build_array(jsonb_build_object('at', now_iso, 'kind', 'cancelled', 'what', 'Cancelled · ' || left(why, 100))))
                          with ordinality as x(e, k) order by k desc limit 60) d))
   where shop_id = p_shop_id and id = q.id;

  -- Who must stop: the yard, if it was packing or out; the salesperson who took it.
  client := coalesce(nullif(btrim(coalesce(q.client_name, '')), ''), nullif(btrim(coalesce(q.payload -> 'client' ->> 'name', '')), ''), 'An order');
  ref := jsonb_build_object('table', 'saved_quotes', 'id', q.id);
  if in_yard then
    perform ow_push(p_shop_id, 'order.cancelled', 'Called off · stop packing',
      lbl || ' · ' || client || ' — ' || coalesce(split_part(who, ' ', 1), 'The Manager') || ' cancelled it. Put back what is out.',
      null, 'order.pick', null, ref, 'cancel:' || q.id || ':yard');
  end if;
  taker := ow_uuid(q.payload ->> 'takenBy');
  if taker is not null and taker is distinct from uid then
    perform ow_push(p_shop_id, 'order.cancelled', 'Order cancelled',
      client || ' ' || lbl || ' — ' || coalesce(split_part(who, ' ', 1), 'The Manager') || ' cancelled it: ' || left(why, 100),
      taker, null, null, ref, 'cancel:' || q.id || ':sales');
  end if;
  if (vm ->> 'amount')::numeric > 0 then
    perform manager_log_decision(p_shop_id, 'order.cancel',
      'Cancelled ' || lbl || ' for ' || client || ' with ' || ow_money((vm ->> 'amount')::numeric) || ' paid: '
        || case when vm ->> 'choice' = 'refund' then 'refunded from ' || (vm ->> 'account') else 'kept as a deposit' end,
      (vm ->> 'amount')::numeric, ref, jsonb_build_object('amountPaid', q.amount_paid), jsonb_build_object('voidMoney', vm));
  end if;
  return jsonb_build_object('ok', true, 'orderId', q.id, 'status', 'cancelled', 'wasInYard', in_yard, 'money', vm);
end $$;
revoke all on function cancel_order(uuid, bigint, text, text, text) from public, anon;
grant execute on function cancel_order(uuid, bigint, text, text, text) to authenticated;

commit;

-- =====================================================================
-- STEP 4  CHECK AFTERWARDS (read-only): every row says ok
-- =====================================================================
select m, case when ok then 'ok' else 'MISSING' end from (values
  ('0171 no sale below cost',            exists (select 1 from pg_trigger where tgname = 'saved_quotes_zz_cost_floor')),
  ('0172 agent total counts charges',    order_shop_total('{"items":[{"sellPrice":1000,"qty":2}],"charges":[{"type":"fixed","value":5000},{"type":"percent","value":10}]}') = 7200),
  ('0173 moving a stage needs its task', exists (select 1 from pg_trigger where tgname = 'saved_quotes_ow_a_stage_move')),
  ('0174 the Checking gate checks',      to_regprocedure('ow_oldest_debt_days(uuid, text)') is not null and position('ow_oldest_debt_days' in pg_get_functiondef('public.saved_quotes_ow_push()'::regprocedure)) > 0),
  ('0175 the Manager''s answers',        exists (select 1 from pg_trigger where tgname = 'saved_quotes_ow_a_decisions')),
  ('0176 void and credit note',          to_regprocedure('void_invoice(uuid, bigint, text, boolean, text, text, uuid)') is not null and to_regprocedure('raise_credit_note(uuid, bigint, jsonb, text, boolean, uuid)') is not null),
  ('0177 one Cancel',                    to_regprocedure('cancel_order(uuid, bigint, text, text, text)') is not null and exists (select 1 from role_tasks where role = 'manager' and task = 'order.cancel')
                                         and position('order.cancel' in pg_get_functiondef('saved_quotes_sales_guard()'::regprocedure)) > 0
                                         and position('order.cancel' in pg_get_functiondef('saved_quotes_stage_move()'::regprocedure)) > 0)
) as t(m, ok);

-- What holds each order in Checking now (price, credit, suppliers, unsourced, prepay):
select id as order_no, client_name, ow_gate_reason(shop_id, payload, amount_paid) as waits_for
  from saved_quotes where status = 'draft' and not voided order by id desc limit 50;
